import heapq
from typing import Dict, List, Optional, Tuple, Any

class Helpdesk:
    PRIORITIES = ("normal", "high", "critical")

    def __init__(self) -> None:
        # Priority mapping for sorting: lower number means higher priority
        self._priority_values = {"critical": 0, "high": 1, "normal": 2}

        # Track customer VIP status
        self._customers: Dict[str, bool] = {}

        # Ticket storage: {ticket_id: {"customer": str, "title": str, "priority": str, "closed": bool}}
        self._tickets: Dict[int, Dict[str, Any]] = {}

        # Ticket counter for unique IDs
        self._next_ticket_id = 1

        # Priority queue for tickets: (priority_score, insertion_order, ticket_id)
        # Priority score calculation:
        # - VIP customers get priority score 0 regardless of ticket priority
        # - Non-VIP customers get priority score based on ticket priority (0=critical, 1=high, 2=normal)
        # - insertion_order ensures FIFO within same priority level
        self._queue: List[Tuple[int, int, int]] = []

        # Counter for insertion order to maintain FIFO within same priority
        self._insertion_counter = 0

    def add_customer(self, name: str, vip: bool = False) -> None:
        self._customers[name] = vip

    def open_ticket(self, customer: str, title: str, priority: str = "normal") -> int:
        if priority not in self.PRIORITIES:
            raise ValueError(f"Priority must be one of {self.PRIORITIES}")

        ticket_id = self._next_ticket_id
        self._next_ticket_id += 1

        # Determine priority score for queue ordering
        if self._customers.get(customer, False):
            # VIP customers have highest priority regardless of ticket priority
            priority_score = 0
        else:
            # Non-VIP customers use ticket priority
            priority_score = self._priority_values[priority]

        # Add to queue with priority score, insertion order, and ticket ID
        heapq.heappush(self._queue, (priority_score, self._insertion_counter, ticket_id))
        self._insertion_counter += 1

        # Store ticket details
        self._tickets[ticket_id] = {
            "customer": customer,
            "title": title,
            "priority": priority,
            "closed": False
        }

        return ticket_id

    def next_ticket(self) -> Optional[int]:
        while self._queue:
            # Get the highest priority ticket
            _, _, ticket_id = heapq.heappop(self._queue)

            # Check if this ticket is still open
            if not self._tickets.get(ticket_id, {}).get("closed", True):
                return ticket_id

        return None

    def close(self, ticket_id: int) -> None:
        if ticket_id not in self._tickets:
            raise ValueError(f"Ticket {ticket_id} does not exist")

        self._tickets[ticket_id]["closed"] = True

    def reopen(self, ticket_id: int) -> None:
        if ticket_id not in self._tickets:
            raise ValueError(f"Ticket {ticket_id} does not exist")

        if self._tickets[ticket_id]["closed"]:
            raise ValueError(f"Cannot reopen closed ticket {ticket_id}")

        # Get ticket details to recalculate priority score
        ticket = self._tickets[ticket_id]
        customer = ticket["customer"]

        # Determine priority score for queue ordering
        if self._customers.get(customer, False):
            priority_score = 0
        else:
            priority_score = self._priority_values[ticket["priority"]]

        # Add back to queue
        heapq.heappush(self._queue, (priority_score, self._insertion_counter, ticket_id))
        self._insertion_counter += 1
